def solve():
    import sys
    it=iter(map(int,sys.stdin.buffer.read().split()))
    n=next(it); A=[next(it) for _ in range(n-1)]
    fac=[]
    for v in A:
        d={}; q=2
        while q*q<=v:
            if v%q==0:
                c=0
                while v%q==0:
                    v//=q; c+=1
                d[q]=c
            q+=1
        if v>1: d[v]=1
        fac.append(d)
    primes=set()
    for d in fac: primes.update(d)
    ans=1
    for p in primes:
        es=[d.get(p,0) for d in fac]
        H=sum(es)
        dp0=[0]*(H+1); dp1=[0]*(H+1)
        power=1
        for x in range(H+1):
            if x==0:
                dp1[x]=1
            else:
                power=power*p%MOD
                dp0[x]=power
        weights=[pow(p,x,MOD) for x in range(H+1)]
        for e in es:
            nd0=[0]*(H+1); nd1=[0]*(H+1)
            if e==0:
                for x in range(H+1):
                    nd0[x]=dp0[x]*weights[x]%MOD
                    nd1[x]=dp1[x]*weights[x]%MOD
            else:
                for x in range(H+1):
                    v0=dp0[x]; v1=dp1[x]
                    y=x+e
                    if y<=H:
                        w=weights[y]
                        nd0[y]=(nd0[y]+v0*w)%MOD
                        nd1[y]=(nd1[y]+v1*w)%MOD
                    y=x-e
                    if y>=0:
                        nd1[y]=(nd1[y]+(v0+v1)*weights[y])%MOD
            dp0,dp1=nd0,nd1
        ans=ans*(sum(dp1)%MOD)%MOD
    print(ans)

if __name__=='__main__': solve()

