        good=[False]*(n+1)
        for t in range(1,n+1):
            v=t
            steps=0
            while v>1:
                v=v.bit_count()
                steps+=1
            good[t]=(steps+1<=k)
        # ways to choose r positions among m
        C=[[0]*(n+1) for _ in range(n+1)]
        for i in range(n+1):
            C[i][0]=C[i][i]=1
            for j in range(1,i):
                C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD
        ans=0
        used=0
        for i,ch in enumerate(s):
            if ch=='1':
                rem=n-i-1
                for t in range(1,n+1):
                    if good[t]:
                        need=t-used
                        if 0<=need<=rem:
                            ans=(ans+C[rem][need])%MOD
                used+=1
        return ans

