        def find(x):
            while par[x]!=x:
                par[x]=par[par[x]]; x=par[x]
            return x
        for i in range(L-1,R):
            s,t=people[i]; a=min(s,t); b=max(s,t)
            x=find(a); y=find(b)
            if x!=y:
                if rank[x]<rank[y]: x,y=y,x
                par[y]=x
                if rank[x]==rank[y]: rank[x]+=1
