        good=True
        for i in range(L-1,R):
            s,t=people[i]; a=min(s,t); b=max(s,t); e=find(a)
            for k in range(a+1,b):
                v=find(k)
                if e==v:
                    good=False; break
                if s<t: u,w=e,v
                else: u,w=v,e
                adj[u].append(w); indeg[w]+=1
