import sys
from collections import deque

def main():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    dist = [[-1] * n for _ in range(n)]
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                q.append((i, j))

    remaining = n * n - sum(row.count(0) for row in dist)  # overwritten below
    remaining = sum(value == -1 for row in dist for value in row)

    while q and remaining:
        u, v = q.popleft()
        next_dist = dist[u][v] + 2

        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            if not left or not right:
                continue
            for x in left:
                row = dist[x]
                for y in right:
                    if row[y] == -1:
                        row[y] = next_dist
                        remaining -= 1
                        q.append((x, y))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == "__main__":
    main()

