                counts=[0]*K
                for c in w:
                    for p in range(K):
                        if counts[p]: seen[p][c]=True
                    counts[c]+=1
                if all(seen[i][j] == ((i,j)!=(a-1,b-1)) for i in range(K) for j in range(K)):
