                for l in range(M-1,-1,-1):
                    if l==0: dp[1].add((c+1,))
                    else:
                        for t in dp[l]: dp[l+1].add(t+(c+1,))
            if len(dp[M])==K**M-1 and target not in dp[M]: ans+=1
        return ans%MOD
    return 0

