class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n,m=len(grid),len(grid[0]); N=n*m
        dirs=[(-1,1),(1,1),(1,-1),(-1,-1)]
        opp={0:2,2:0,1:2}
        straight=[[[0]*N for _ in range(3)] for _ in range(4)]
        # replace with compact arrays
        straight=[[array('H',[0])*N for _ in range(3)] for _ in range(4)]
        for d,(dr,dc) in enumerate(dirs):
            rows=range(n-1,-1,-1) if dr>0 else range(n)
            cols=range(m-1,-1,-1) if dc>0 else range(m)
            for i in rows:
                for j in cols:
                    p=i*m+j; ni=i+dr; nj=j+dc
                    for e in (0,1,2):
                        if grid[i][j]==e:
                            val=1
                            ne=opp[e]
                            if 0<=ni<n and 0<=nj<m: val+=straight[d][ne][ni*m+nj]
                            straight[d][e][p]=val
        free=[[array('H',[0])*N for _ in range(3)] for _ in range(4)]
        for d,(dr,dc) in enumerate(dirs):
            nd=(d+1)%4; tr,tc=dirs[nd]
            rows=range(n-1,-1,-1) if dr>0 else range(n)
            cols=range(m-1,-1,-1) if dc>0 else range(m)
            for i in rows:
                for j in cols:
                    p=i*m+j; ni=i+dr; nj=j+dc; ti=i+tr; tj=j+tc
                    for e in (0,1,2):
                        if grid[i][j]!=e: continue
                        ne=opp[e]; best=0
                        if 0<=ni<n and 0<=nj<m: best=free[d][ne][ni*m+nj]
                        if 0<=ti<n and 0<=tj<m: best=max(best,straight[nd][ne][ti*m+tj])
                        free[d][e][p]=1+best
        ans=0
        for i in range(n):
            for j in range(m):
                if grid[i][j]==1:
                    p=i*m+j
                    for d in range(4): ans=max(ans,free[d][1][p])
        return ans

