from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def count(o: int, e: int, length: int, first_parity: int) -> int:
            need_o = (length + 1) // 2 if first_parity == 1 else length // 2
            return fact[o] * fact[e] if o == need_o and e == length - need_o else 0

        total = count(odds, evens, n, 1) + count(odds, evens, n, 0)
        if k > total:
            return []
        avail = list(range(1, n + 1))
        ans = []
        prev = None
        while avail:
            for x in avail:
                if prev is not None and x % 2 == prev % 2:
                    continue
                o = sum(v % 2 for v in avail if v != x)
                e = len(avail) - 1 - o
                length = len(avail) - 1
                ways = count(o, e, length, 1 - (x % 2))
                if k > ways:
                    k -= ways
                else:
                    ans.append(x)
                    avail.remove(x)
                    prev = x
                    break
            else:
                return []
        return ans

