class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            if n % 2 and i == m - 1:
                c = powers[i]
            else:
                c = (powers[i] + powers[n - 1 - i]) % k
            coeff.append(c)

        reachable = [None] * (m + 1)
        reachable[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            row = bytearray(k)
            nxt = reachable[i + 1]
            c = coeff[i]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        row[(r + d * c) % k] = 1
            reachable[i] = row

        digits = []
        residue = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-residue - d * c) % k
                if reachable[i + 1][need]:
                    digits.append(str(d))
                    residue = (residue + d * c) % k
                    break
        half = ''.join(digits)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

