import sys

def solve():
    data=sys.stdin.buffer.read().split()
    if not data: return
    it=iter(data); t=int(next(it)); out=[]
    MOD=998244353
    for _ in range(t):
        h=int(next(it)); w=int(next(it))
        grid=[next(it).decode() for _ in range(h)]
        # Transfer-matrix trace over vertical boundary states. Each row's
        # horizontal periodic configurations induce transitions between
        # top and bottom edge masks.
        if w>18:
            # The frontier direction may be transposed to minimize width.
            # (The constraints of the original problem keep the effective
            # frontier small.)
            grid=[''.join(grid[i][j] for i in range(h)) for j in range(w)]
            h,w=w,h
        n=1<<w
        ans=0
        # Compute trace by fixing the top boundary mask and propagating rows.
        for start in range(n):
            dp={start:1}
            for r in range(h):
                ndp={}
                typ=grid[r]
                for top,val in dp.items():
                    # Sweep around the row; enumerate the left boundary bit,
                    # requiring it to equal the final right edge.
                    for first in (0,1):
                        cur={(0,first):val}
                        for c in range(w):
                            nxt={}
                            up=(top>>c)&1
                            for (botmask,left),ways in cur.items():
                                for right in (0,1):
                                    for down in (0,1):
                                        if left+right+up+down!=2: continue
                                        a=typ[c]==ord('A')
                                        # A permits adjacent pairs only;
                                        # B permits opposite pairs only.
                                        opposite=(left==right and up==down and left!=up)
                                        if (a and opposite) or ((not a) and not opposite): continue
                                        key=(botmask|(down<<c),right)
                                        nxt[key]=(nxt.get(key,0)+ways)%MOD
                            cur=nxt
                        for (bot,right),ways in cur.items():
                            if right==first:
                                ndp[bot]=(ndp.get(bot,0)+ways)%MOD
                dp=ndp
            ans=(ans+dp.get(start,0))%MOD
        out.append(str(ans))
    print('\n'.join(out))

if __name__=='__main__': solve()

