import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    k = 2
    for _ in range(m):
        x, y, z = data[k]-1, data[k+1]-1, data[k+2]
        k += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    pot = [-1] * n
    ans = [0] * n
    for start in range(n):
        if pot[start] != -1:
            continue
        pot[start] = 0
        q = [start]
        comp = []
        for v in q:
            comp.append(v)
            pv = pot[v]
            for to, z in adj[v]:
                want = pv ^ z
                if pot[to] == -1:
                    pot[to] = want
                    q.append(to)
                elif pot[to] != want:
                    print(-1)
                    return
        ones = [0] * 31
        for v in comp:
            x = pot[v]
            for b in range(31):
                ones[b] += (x >> b) & 1
        root = 0
        size = len(comp)
        for b in range(31):
            if ones[b] > size - ones[b]:
                root |= 1 << b
        for v in comp:
            ans[v] = pot[v] ^ root
    print(*ans)

if __name__ == '__main__':
    main()

