import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, W = data[0], data[1]
    items = data[2:]
    neg = -(10**100)
    dp = [neg] * (W + 1)
    dp[0] = 0

    for z in range(n):
        w, v = items[2 * z], items[2 * z + 1]
        ndp = [neg] * (W + 1)
        for r in range(min(w, W + 1)):
            hull = deque()
            for j in range((W - r) // w + 1):
                idx = r + j * w
                old = dp[idx]
                if old != neg:
                    m = 2 * j
                    b = old - j * j - j * v
                    while len(hull) >= 2:
                        m1, b1 = hull[-2]
                        m2, b2 = hull[-1]
                        if (b1 - b2) * (m - m2) >= (b2 - b) * (m2 - m1):
                            hull.pop()
                        else:
                            break
                    hull.append((m, b))
                while len(hull) >= 2 and hull[1][0] * j + hull[1][1] >= hull[0][0] * j + hull[0][1]:
                    hull.popleft()
                if hull:
                    m, b = hull[0]
                    ndp[idx] = -j * j + j * v + m * j + b
        dp = ndp
    print(max(dp))

if __name__ == '__main__':
    main()

