from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        post = []
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                post.append(v)
            else:
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))

        sizes = [1] * n
        for v in post:
            for c in children[v]:
                sizes[v] += sizes[c]

        pos = [0] * n
        chars = []
        for i, v in enumerate(post):
            pos[v] = i
            chars.append(s[v])
        t = ''.join(chars)

        # Manacher odd radii: d1[i] includes the center.
        d1 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        # Even radii: center is between i-1 and i.
        d2 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for v in range(n):
            length = sizes[v]
            left = pos[v] - length + 1
            if length % 2:
                center = (left + pos[v]) // 2
                ans[v] = d1[center] >= (length + 1) // 2
            else:
                center = (left + pos[v] + 1) // 2
                ans[v] = d2[center] >= length // 2
        return ans

