from itertools import permutations

MOD = 998244353

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].decode()
    whites = [i for i, c in enumerate(s) if c == 'W']
    blacks = [i for i, c in enumerate(s) if c == 'B']
    ans = 0
    for p in permutations(blacks):
        # p[j] is the black vertex paired with whites[j].
        # Every cut must have a matched white to its right and black to its left.
        farthest = -1
        intervals = []
        for w, b in zip(whites, p):
            if b < w:
                intervals.append((b, w))
        covered = [False] * (2 * n - 1)
        for b, w in intervals:
            for cut in range(b, w):
                covered[cut] = True
        if all(covered):
            ans += 1
    print(ans % MOD)

if __name__ == '__main__':
    main()

