import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    N,M=data[0],data[1]
    pieces=[]
    occupied=set()
    for k in range(M):
        a,b=data[2+2*k],data[3+2*k]
        code=(a-1)*N+(b-1)
        pieces.append((a,b))
        occupied.add(code)
    targets=[]
    moves=((2,1),(1,2),(-1,2),(-2,1),(-2,-1),(-1,-2),(1,-2),(2,-1))
    for a,b in pieces:
        for da,db in moves:
            x,y=a+da,b+db
            if 1<=x<=N and 1<=y<=N:
                code=(x-1)*N+y-1
                if code not in occupied:
                    targets.append(code)
    targets.sort()
    attacked=0
    prev=-1
    for code in targets:
        if code!=prev:
            attacked+=1
            prev=code
    print(N*N-M-attacked)

if __name__=='__main__': main()

