class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        # Values ending in a given drink at each hour.
        a2 = b2 = 0  # value two hours back
        a1 = b1 = 0  # value one hour back
        for i in range(n):
            a = energyDrinkA[i] + max(a1, b2)
            b = energyDrinkB[i] + max(b1, a2)
            a2, a1 = a1, a
            b2, b1 = b1, b
        return max(a1, b1)

