class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        dp = [1] * 26
        for _ in range(t):
            ndp = [0] * 26
            for i in range(25):
                ndp[i] = dp[i + 1]
            ndp[25] = (dp[0] + dp[1]) % mod
            dp = ndp
        return sum(dp[ord(ch) - 97] for ch in s) % mod

