from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0
        # Li Chao tree for maximum lines on integer x in [0, n-1].
        tree = [None] * (4 * n)

        def insert(node, left, right, line):
            cur = tree[node]
            if cur is None:
                tree[node] = line
                return
            mid = (left + right) // 2
            # Keep the line best at mid in this node.
            if line[0] * mid + line[1] > cur[0] * mid + cur[1]:
                tree[node], line = line, cur
                cur = tree[node]
            if left == right:
                return
            if line[0] * left + line[1] > tree[node][0] * left + tree[node][1]:
                insert(node * 2, left, mid, line)
            elif line[0] * right + line[1] > tree[node][0] * right + tree[node][1]:
                insert(node * 2 + 1, mid + 1, right, line)

        def query(node, left, right, x):
            line = tree[node]
            best = line[0] * x + line[1] if line is not None else -10**30
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                return max(best, query(node * 2, left, mid, x))
            return max(best, query(node * 2 + 1, mid + 1, right, x))

        insert(1, 0, n - 1, (nums[0], 0))
        answer = 0
        for j in range(1, n):
            dp = query(1, 0, n - 1, j)
            answer = dp
            insert(1, 0, n - 1, (nums[j], dp - j * nums[j]))
        return answer

