class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        for x in sorted(counts, reverse=True):
            rem = total - x
            if rem % 2 == 0:
                y = rem // 2
                if counts[y] >= (2 if y == x else 1):
                    return x
        return 0

