import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        lo = 10 ** (len(str(n)) - 1)
        hi = 10 ** len(str(n))
        prime = [True] * hi
        prime[0] = False
        if hi > 1:
            prime[1] = False
        for p in range(2, int((hi - 1) ** 0.5) + 1):
            if prime[p]:
                prime[p*p:hi:p] = [False] * (((hi - 1 - p*p) // p) + 1)
        if prime[n] or prime[m]:
            return -1
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if dist[x] != cost:
                continue
            if x == m:
                return cost
            s = list(str(x))
            for i, ch in enumerate(s):
                d = int(ch)
                for nd in (d - 1, d + 1):
                    if 0 <= nd <= 9 and not (i == 0 and nd == 0):
                        t = int(''.join(s[:i] + [str(nd)] + s[i+1:]))
                        if not prime[t] and cost + t < dist.get(t, 10**30):
                            dist[t] = cost + t
                            heapq.heappush(pq, (cost + t, t))
        return -1

