        dp = [[INF] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, n // 2):
            ndp = [[INF] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue
                    pair_cost = cost[i][a] + cost[n - 1 - i][b]
                    best = INF
                    for pa in range(3):
                        for pb in range(3):
                            if pa != pb and pa != a and pb != b:
